#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct step {
    ll val;
    int cost;
    bool operator>(const step &c) const {
        return cost > c.cost;
    }
};

unordered_set<ll> visited;

bool wasVisited(ll c) {
    return visited.find(c) != visited.end();
}

step uupper(ll n) {
    ll res = 0;
    int i = 0;
    while (res < n) {
        res = res * 10 + 1;
        i++;
    }
    return {res, i};
}

step upper(ll n) {
    ll res = 0;
    int i = 0;
    while (res * 10 + 1 <= n) {
        res = res * 10 + 1;
        i++;
    }
    ll resmul = res;
    int imul = i;
    while (res < n) {
        res += resmul;
        i += imul;
    }
    return {res, i};
}

step lower(ll n) {
    ll res = 0;
    int i = 0;
    while (res * 10 + 1 <= n) {
        res = res * 10 + 1;
        i++;
    }
    ll resmul = res;
    int imul = i;
    while (res + resmul <= n) {
        res += resmul;
        i += imul;
    }
    return {res, i};
}

int main(int argc, char **argv) {
    ll n;
    cin >> n;
    priority_queue<step, vector<step>, greater<step>> pq;
    pq.push({n, 0});
    while (pq.top().val != 0) {
        ll val = pq.top().val;
        int cost = pq.top().cost;
        pq.pop();
        if (wasVisited(val))
            continue;
        visited.insert(val);
        for (step next : {lower(val), upper(val), uupper(val)}) {
            next.cost += cost;
            next.val = abs(val - next.val);
            pq.push(next);
        }
    }
    cout << pq.top().cost << endl;
    return 0;
}
